  if (!f.endsWith(".feature")) continue;
  const src = fs.readFileSync(path.join(featureDir,f),"utf8");
  const lines = src.split("\n");
  let inScenario = false, cur = null;
  for (const line of lines) {
    const m = line.match(/^  Scenario: (.+)$/);
